import "../../styles/style.css";
import ActionList from "../../components/main/ActionList";
import AppHeader from "../../components/main/AppHeader";
import ChatInput from "../../components/main/ChatInput";
import ChatSidebar from "../../components/main/ChatSidebar";
import ChatWindow from "../../components/main/ChatWindow";
import DataPreviewModal from "../../components/main/DataPreviewModal";
import DatasetSidebar from "../../components/main/DatasetSidebar";
import HistoryModal from "../../components/main/HistoryModal";
import useMainPage from "../../hooks/useMainPage";

export default function MainPage() {
  const {
    uploaded,
    datasetName,
    rows,
    columns,
    uploadError,
    tableData,
    tableDataBefore,
    headers,
    headersBefore,
    showPreview,
    setShowPreview,
    selectedActions,
    inputValue,
    setInputValue,
    showHistory,
    setShowHistory,
    historyLogs,
    isLoadingChat,
    chatError,
    pendingFeedback,
    submittingFeedback,
    stepTitle,
    fileInputRef,
    chatEndRef,
    actions,
    chats,
    activeChatId,
    sidebarCollapsed,
    setSidebarCollapsed,
    activeChat,
    handleNewChat,
    handleSwitchChat,
    handleRenameChat,
    handleDeleteChat,
    handleUploadClick,
    handleFileUpload,
    handleReset,
    handleDownload,
    handleShowHistory,
    handleAutoClean,
    handleSend,
    handleFeedback,
    toggleAction,
    DatasetIcon,
    canSend,
    autoCleanDisabled,
  } = useMainPage();

  return (
    <div className="container">
      <ChatSidebar
        sidebarCollapsed={sidebarCollapsed}
        setSidebarCollapsed={setSidebarCollapsed}
        handleNewChat={handleNewChat}
        chats={chats}
        activeChatId={activeChatId}
        setActiveChatId={handleSwitchChat}
        handleRenameChat={handleRenameChat}
        handleDeleteChat={handleDeleteChat}
      />

      <DatasetSidebar
        fileInputRef={fileInputRef}
        handleFileUpload={handleFileUpload}
        uploaded={uploaded}
        handleUploadClick={handleUploadClick}
        uploadError={uploadError}
        DatasetIcon={DatasetIcon}
        datasetName={datasetName}
        rows={rows}
        columns={columns}
        setShowPreview={setShowPreview}
        handleDownload={handleDownload}
        handleShowHistory={handleShowHistory}
        handleReset={handleReset}
        handleAutoClean={handleAutoClean}
        autoCleanDisabled={autoCleanDisabled}
        pendingFeedback={pendingFeedback}
      />

      <div className="main">
        <AppHeader />
        <ChatWindow
          activeChat={activeChat}
          chatEndRef={chatEndRef}
          pendingFeedback={pendingFeedback}
          onAcceptFeedback={() => handleFeedback(true)}
          onRejectFeedback={() => handleFeedback(false)}
          feedbackDisabled={submittingFeedback}
          stepTitle={stepTitle}
        />
        <ActionList
          actions={actions}
          uploaded={uploaded}
          selectedActions={selectedActions}
          onActionClick={toggleAction}
          isLoading={isLoadingChat || pendingFeedback}
        />
        {chatError && (
          <div className="chat-error">
            {chatError}
          </div>
        )}
        {isLoadingChat && (
          <div className="chat-loading">
            Processing...
          </div>
        )}
        <ChatInput
          inputValue={inputValue}
          setInputValue={setInputValue}
          handleSend={handleSend}
          canSend={canSend}
          isLoading={isLoadingChat || pendingFeedback}
        />
      </div>

      {showPreview && (
        <DataPreviewModal
          onClose={() => setShowPreview(false)}
          data={tableData}
          dataBefore={tableDataBefore}
          headers={headers}
          headersBefore={headersBefore}
          datasetName={datasetName}
        />
      )}
      {showHistory && (
        <HistoryModal
          onClose={() => setShowHistory(false)}
          logs={historyLogs}
        />
      )}
    </div>
  );
}
